# Generates the WiX v4 fragment for one bundled tool (git, svn or hg): the
# directory tree under 3rdparty\<tool> and one component per file, collected in
# the component group <Tool>Files that Sourcerer.wxs references.
#
# Ids and GUIDs are derived from the tool name and the relative path of each
# file or directory, so the output only changes when the file set changes.
# A file keeps its component GUID for as long as it keeps its path.
#
# -OwnsThirdPartyDir also declares the shared 3rdparty directory; exactly one
# tool fragment (git) must pass it.
#
# Windows PowerShell 5.1 runs it (build-installer-wix.bat).

param(
    [Parameter(Mandatory = $true)][string]$ToolName,
    [Parameter(Mandatory = $true)][string]$SourceDir,
    [Parameter(Mandatory = $true)][string]$OutFile,
    [switch]$OwnsThirdPartyDir
)

$ErrorActionPreference = 'Stop'

if (-not (Test-Path -PathType Container $SourceDir)) {
    throw "Source directory not found: $SourceDir"
}
$root = (Resolve-Path $SourceDir).ProviderPath.TrimEnd('\')
$tool = $ToolName.ToLowerInvariant()
$prefix = $tool.Substring(0, 1).ToUpperInvariant() + $tool.Substring(1)

$md5 = [System.Security.Cryptography.MD5]::Create()
function Get-Md5Bytes([string]$Text) {
    $md5.ComputeHash([System.Text.Encoding]::UTF8.GetBytes($Text))
}
function Get-HashId([string]$Kind, [string]$RelativePath) {
    $bytes = Get-Md5Bytes "$tool|$Kind|$($RelativePath.ToLowerInvariant())"
    return ($bytes | ForEach-Object { $_.ToString('x2') }) -join ''
}
function Get-StableGuid([string]$RelativePath) {
    $bytes = Get-Md5Bytes "$tool|guid|$($RelativePath.ToLowerInvariant())"
    return ([guid]::new([byte[]]$bytes)).ToString()
}
function Get-RelativePath([string]$FullPath) {
    return $FullPath.Substring($root.Length + 1)
}
function Get-DirId([string]$RelativeDir) {
    if ($RelativeDir -eq '') {
        return "${prefix}RootDir"
    }
    return "${prefix}Dir_$(Get-HashId 'dir' $RelativeDir)"
}
function ConvertTo-Xml([string]$Text) {
    return [System.Security.SecurityElement]::Escape($Text)
}

$comparer = [System.StringComparer]::OrdinalIgnoreCase
$lines = New-Object System.Collections.Generic.List[string]

function Add-DirectoryTree([string]$FullDir, [string]$Indent) {
    [string[]]$names = @(Get-ChildItem -LiteralPath $FullDir -Directory -Force |
        ForEach-Object { $_.Name })
    [System.Array]::Sort($names, $comparer)
    foreach ($name in $names) {
        $full = Join-Path $FullDir $name
        $relative = Get-RelativePath $full
        $lines.Add("$Indent<Directory Id=""$(Get-DirId $relative)"" Name=""$(ConvertTo-Xml $name)"">")
        Add-DirectoryTree $full "$Indent  "
        $lines.Add("$Indent</Directory>")
    }
}

$lines.Add('<?xml version="1.0" encoding="UTF-8"?>')
$lines.Add('<!-- Generated by installer\3rdparty\generate-3rdparty-wxs.ps1. Do not edit. -->')
$lines.Add('<Wix xmlns="http://wixtoolset.org/schemas/v4/wxs">')
if ($OwnsThirdPartyDir) {
    $lines.Add('  <Fragment>')
    $lines.Add('    <DirectoryRef Id="INSTALLFOLDER">')
    $lines.Add('      <Directory Id="ThirdPartyDir" Name="3rdparty" />')
    $lines.Add('    </DirectoryRef>')
    $lines.Add('  </Fragment>')
}
$lines.Add('  <Fragment>')
$lines.Add('    <DirectoryRef Id="ThirdPartyDir">')
$lines.Add("      <Directory Id=""${prefix}RootDir"" Name=""$tool"">")
Add-DirectoryTree $root '        '
$lines.Add('      </Directory>')
$lines.Add('    </DirectoryRef>')
$lines.Add('  </Fragment>')

[string[]]$files = @(Get-ChildItem -LiteralPath $root -Recurse -File -Force |
    ForEach-Object { Get-RelativePath $_.FullName })
[System.Array]::Sort($files, $comparer)
if ($files.Count -eq 0) {
    throw "No files found in $SourceDir"
}

$lines.Add('  <Fragment>')
$lines.Add("    <ComponentGroup Id=""${prefix}Files"">")
foreach ($relative in $files) {
    $id = "${prefix}File_$(Get-HashId 'file' $relative)"
    $slash = $relative.LastIndexOf('\')
    $dirId = if ($slash -lt 0) { Get-DirId '' } else { Get-DirId $relative.Substring(0, $slash) }
    $source = ConvertTo-Xml "`$(var.SourcererBinPath)\3rdparty\$tool\$relative"
    $lines.Add("      <Component Id=""$id"" Guid=""$(Get-StableGuid $relative)"" Directory=""$dirId"">")
    $lines.Add("        <File Id=""${id}_f"" Source=""$source"" KeyPath=""yes"" />")
    $lines.Add('      </Component>')
}
$lines.Add('    </ComponentGroup>')
$lines.Add('  </Fragment>')
$lines.Add('</Wix>')

$text = ($lines -join "`r`n") + "`r`n"
[System.IO.File]::WriteAllText($OutFile, $text, (New-Object System.Text.UTF8Encoding $true))
Write-Host "Wrote $OutFile ($($files.Count) files)"
